// Mechanical mask preparation/merge only. Artwork is generated by the bundled Imagegen CLI.
// No catalog, target map, or live scene is changed by this utility.
import sharp from 'sharp';
import fs from 'node:fs/promises';
import path from 'node:path';
const root = process.cwd();
const source = path.join(root, 'output/imagegen/journey-marrakech-v5-wide-festival.png');
const dir = path.join(root, 'output/imagegen/journey-marrakech-v6-evidence');
const regions = [
  { id: 'remove-slipper', x: 730, y: 1830, w: 280, h: 192 },
  { id: 'remove-key', x: 2500, y: 1880, w: 368, h: 222 },
  { id: 'remove-gecko', x: 1450, y: 1760, w: 162, h: 110 },
  { id: 'remove-camel', x: 2078, y: 1738, w: 252, h: 258 },
  { id: 'add-slipper', x: 1240, y: 1200, w: 180, h: 110 },
  { id: 'add-key', x: 1810, y: 1485, w: 180, h: 98 },
  { id: 'add-gecko', x: 2170, y: 1220, w: 205, h: 112 },
  { id: 'add-camel', x: 1680, y: 720, w: 130, h: 164 },
];
await fs.mkdir(dir, { recursive: true });
const W = 3840, H = 2160;
const alpha = Buffer.alloc(W * H * 4, 255);
for (const r of regions) for (let y=r.y; y<r.y+r.h; y++) for (let x=r.x; x<r.x+r.w; x++) alpha[(y*W+x)*4+3]=0;
const maskPath = path.join(dir, 'edit-mask.png');
await sharp(alpha, {raw:{width:W,height:H,channels:4}}).png().toFile(maskPath);
await fs.writeFile(path.join(dir, 'regions.json'), JSON.stringify({source, width:W, height:H, regions}, null, 2)+'\n');
const outlines = regions.map(r=>`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="none" stroke="${r.id.startsWith('remove')?'#ff0055':'#00ffff'}" stroke-width="5"/><text x="${r.x}" y="${r.y-8}" font-size="24" fill="white" stroke="black" stroke-width="0.5">${r.id}</text>`).join('');
await sharp(source).composite([{input:Buffer.from(`<svg width="${W}" height="${H}">${outlines}</svg>`)}]).png().toFile(path.join(dir,'mask-guide.png'));
if (process.argv.includes('--merge')) {
  const generated = path.join(root, 'output/imagegen/journey-marrakech-v6-api-edit.png');
  const meta = await sharp(generated).metadata();
  if (meta.width!==W || meta.height!==H) throw new Error('Generated canvas changed dimensions');
  const base = await sharp(source).removeAlpha().raw().toBuffer();
  const edit = await sharp(generated).removeAlpha().raw().toBuffer();
  const result = Buffer.from(base);
  // 6px boundary blend into exact original, entirely inside each authorized mask rectangle.
  for (const r of regions) for(let y=r.y; y<r.y+r.h; y++) for(let x=r.x; x<r.x+r.w; x++) {
    const d=Math.min(x-r.x,y-r.y,r.x+r.w-1-x,r.y+r.h-1-y);
    const a=Math.min(1,d/6);
    const i=(y*W+x)*3;
    for(let c=0;c<3;c++) result[i+c]=Math.round(base[i+c]*(1-a)+edit[i+c]*a);
  }
  let changedOutside=0, changedInside=0;
  for(let y=0;y<H;y++) for(let x=0;x<W;x++) {
    const i=(y*W+x)*3;
    if(result[i]!==base[i] || result[i+1]!==base[i+1] || result[i+2]!==base[i+2]) {
      if(regions.some(r=>x>=r.x&&x<r.x+r.w&&y>=r.y&&y<r.y+r.h)) changedInside++;
      else changedOutside++;
    }
  }
  if(changedOutside) throw new Error('Protected source pixels changed');
  const finalPath=path.join(root,'output/imagegen/journey-marrakech-v6-inner-targets.png');
  await sharp(result,{raw:{width:W,height:H,channels:3}}).png().toFile(finalPath);
  for(const r of regions) {
    const rect={left:r.x-35,top:r.y-35,width:r.w+70,height:r.h+70};
    await sharp(finalPath).extract(rect).png().toFile(path.join(dir,r.id+'.png'));
  }
  await fs.writeFile(path.join(dir,'preservation.json'),JSON.stringify({changedOutside,changedInside,finalPath,featherPixels:6},null,2)+'\n');
  console.log(JSON.stringify({finalPath,changedOutside,changedInside}));
} else console.log(JSON.stringify({maskPath, regions:regions.length}));
